const EMAILJS_PUBLIC_KEY="wrNv2DhKAGsh-yE6g";const EMAILJS_SERVICE_ID="service_5wxik6g";const EMAILJS_TEMPLATE_ID="template_eb36ya5";if(window.emailjs){emailjs.init({publicKey:EMAILJS_PUBLIC_KEY})}let allowedDomains=[];let allowedSpecificEmails=[];let whitelistLoaded=false;let whitelistLoadFailed=false;async function loadEmailWhitelist(){try{const t=await fetch("./allowed-emails.json",{cache:"no-store"});if(!t.ok)throw new Error("Failed to fetch whitelist");const e=await t.json();allowedDomains=(e.allowedDomains||[]).map(function(t){return t.toLowerCase()});allowedSpecificEmails=(e.allowedSpecificEmails||[]).map(function(t){return t.toLowerCase()});whitelistLoaded=true}catch(t){console.error("Could not load allowed-emails.json:",t);whitelistLoadFailed=true}finally{updateSendButtonState()}}const contactForm=document.getElementById("contactForm");const nameInput=document.getElementById("Name");const emailInput=document.getElementById("E_mail");const messageInput=document.getElementById("Message");const sendBtn=document.getElementById("sendBtn");const statusEl=document.getElementById("formStatus");const hpField=document.getElementById("hp_field");const captchaQuestion=document.getElementById("captchaQuestion");const captchaAnswerInput=document.getElementById("captchaAnswer");let captchaCorrectAnswer=null;function generateCaptcha(){const t=Math.floor(Math.random()*10)+1;const e=Math.floor(Math.random()*10)+1;captchaCorrectAnswer=t+e;if(captchaQuestion){captchaQuestion.textContent="Human check: "+t+" + "+e+" = ?"}if(captchaAnswerInput){captchaAnswerInput.value=""}}function containsSuspiciousContent(t){const e=/<[^>]*>/;const n=/javascript:|on\w+\s*=/i;const a=/(https?:\/\/){3,}/i;return e.test(t)||n.test(t)||a.test(t)}function isPlainTextSafe(t){const e=/^[\p{L}\p{N}\s.,!?'"()\-:;@#&/]*$/u;return e.test(t)&&!containsSuspiciousContent(t)}function isValidEmailFormat(t){const e=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;return e.test(t)}function isTrustedEmailDomain(t){const e=t.toLowerCase();const n=e.split("@")[1];if(!n)return false;if(allowedSpecificEmails.includes(e))return true;return allowedDomains.includes(n)}function updateSendButtonState(){const t=nameInput.value.trim();const e=emailInput.value.trim();const n=messageInput.value.trim();const a=t.length>0&&e.length>0&&n.length>0;const s=isPlainTextSafe(t);const o=isPlainTextSafe(n);const l=isValidEmailFormat(e);const i=a&&s&&o&&l&&whitelistLoaded;sendBtn.disabled=!i;if(whitelistLoadFailed){statusEl.textContent="Could not load email whitelist — please refresh the page.";statusEl.style.color="#c0392b"}}[nameInput,emailInput,messageInput].forEach(function(t){t.addEventListener("input",function(){statusEl.textContent="";updateSendButtonState()})});if(contactForm){generateCaptcha();loadEmailWhitelist();contactForm.addEventListener("submit",function(t){t.preventDefault();const e=nameInput.value.trim();const n=emailInput.value.trim();const a=messageInput.value.trim();if(!e||!n||!a){statusEl.textContent="Please fill in all fields.";statusEl.style.color="#c0392b";return}if(!isPlainTextSafe(e)||!isPlainTextSafe(a)){statusEl.textContent="Name and message can only contain plain text — no code or links.";statusEl.style.color="#c0392b";return}if(!isValidEmailFormat(n)){statusEl.textContent="Please enter a valid email address.";statusEl.style.color="#c0392b";return}if(!isTrustedEmailDomain(n)){statusEl.textContent="Please use an email from a recognized provider (Gmail, Outlook, Yahoo, etc.) or your organization email.";statusEl.style.color="#c0392b";return}if(hpField&&hpField.value.trim()!==""){statusEl.textContent="Submission blocked.";statusEl.style.color="#c0392b";return}const s=parseInt(captchaAnswerInput.value.trim(),10);if(isNaN(s)||s!==captchaCorrectAnswer){statusEl.textContent="Human check failed — please solve the math question correctly.";statusEl.style.color="#c0392b";generateCaptcha();return}if(EMAILJS_PUBLIC_KEY=="wrNv2DhKAGsh-yE6g"){statusEl.textContent="Form is wired up — add your EmailJS keys in script.js to go live.";statusEl.style.color="#c0392b";return}sendBtn.disabled=true;sendBtn.textContent="SENDING...";statusEl.textContent="";emailjs.send(EMAILJS_SERVICE_ID,EMAILJS_TEMPLATE_ID,{from_name:e,reply_to:n,message:a}).then(function(){statusEl.textContent="Message sent successfully! I'll get back to you soon.";statusEl.style.color="#15803d";contactForm.reset();generateCaptcha()}).catch(function(t){statusEl.textContent="Something went wrong. Please try again or email me directly.";statusEl.style.color="#c0392b";console.error("EmailJS error:",t)}).finally(function(){sendBtn.textContent="SEND";updateSendButtonState()})})}
